output_text:
[
  {
    "id": "no_cart_in_single_file",
    "text": "Shopping carts are prohibited in one-cell-wide product aisles between opposing shelves.",
    "abstraction": {
      "state_properties": {
        "single_file_product_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_product_aisle"
        ]
      }
    }
  },
  {
    "id": "no_drive_cart_into_single_file",
    "text": "An agent must not move a cart from a wider aisle into a one-cell-wide product aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_product_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_product_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "drop_cart_only_at_aisle_mouth",
    "text": "A cart may only be parked at the mouth of a single-file product aisle, not at arbitrary shelf locations.",
    "abstraction": {
      "state_properties": {
        "single_file_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "single_file_mouth"
          }
        ]
      }
    }
  },
  {
    "id": "parked_cart_implies_enter_aisle",
    "text": "If an agent parks the cart at a single-file aisle mouth, they are obliged to enter that aisle without the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_product_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "drop_cart_at_mouth": {
          "pre": {
            "and": [
              "single_file_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enter_single_file_without_cart": {
          "pre": {
            "and": [
              "single_file_mouth",
              {
                "not": "hasCart"
              },
              "N"
            ]
          },
          "post": "single_file_product_aisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "drop_cart_at_mouth",
      "discharge": "enter_single_file_without_cart"
    }
  },
  {
    "id": "retrieve_after_single_file_pick",
    "text": "After collecting an item while cartless in a single-file aisle, the agent must return to the aisle mouth and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_product_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartless_single_file_pick": {
          "pre": {
            "and": [
              "single_file_product_aisle",
              {
                "not": "hasCart"
              },
              "adjShelf",
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieve_cart_at_mouth": {
          "pre": {
            "and": [
              "single_file_mouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartless_single_file_pick",
      "discharge": "retrieve_cart_at_mouth"
    }
  },
  {
    "id": "no_cartless_wandering",
    "text": "Except at the entrance/cart bay or during a single-file-aisle excursion, agents should not move around the supermarket without their cart.",
    "abstraction": {
      "state_properties": {
        "entrance_or_cart_bay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "single_file_product_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowed_cartless_area": {
          "or": [
            "entrance_or_cart_bay",
            "single_file_product_aisle",
            "single_file_mouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowed_cartless_area"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_normal_shelf",
    "text": "Shelf interactions outside single-file product aisles must be performed with the cart present.",
    "abstraction": {
      "state_properties": {
        "single_file_product_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "normal_shelf_position": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_product_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "normal_shelf_position",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_in_two_wide_bays",
    "text": "In two-wide shelf service bays or tight shelf-side passages, agents must keep the cart with them when interacting with shelves.",
    "abstraction": {
      "state_properties": {
        "single_file_product_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "two_wide_service_bay": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_product_aisle"
            },
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    2
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "two_wide_service_bay",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
